{
  "summary": "We cannot calculate the exact Enhanced CPF Housing Grant amount, but here is what you need to know and do next.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "caveat",
      "text": "The exact amount of the Enhanced CPF Housing Grant (EHG) depends on factors such as household income, flat type, and the latest HDB grant rates, which may change over time."
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "For first‑timer married couples who are Singapore Citizens, the EHG is available for 2‑room, 3‑room, 4‑room, and 5‑room BTO flats, with the grant amount decreasing as household income rises."
    },
    {
      "claim_id": "c3",
      "kind": "policy_fact",
      "text": "As of the most recent HDB guidelines, households with a monthly combined income of up to $14,000 may be eligible for the EHG, but the exact grant amount is tiered (e.g., higher for lower incomes)."
    },
    {
      "claim_id": "c4",
      "kind": "preparation_step",
      "text": "Check the latest EHG rates on the HDB website (hdb.gov.sg) or the HDB Flat Portal to see the grant amount that corresponds to a $9,000 monthly household income for a 4‑room BTO."
    },
    {
      "claim_id": "c5",
      "kind": "preparation_step",
      "text": "Prepare your latest payslips, Income Tax Notices of Assessment, and CPF contribution statements, as HDB will require these documents to verify your household income for the grant application."
    },
    {
      "claim_id": "c6",
      "kind": "preparation_step",
      "text": "If you have not yet received your HDB Flat Eligibility (HFE) letter, apply for it early, as the HFE is required before you can submit a BTO application and claim any grants."
    }
  ],
